using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries')")] string key)
    {
        var config = AppConfiguration.Current;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("Update a configuration value at runtime.")]
    public static string SetConfigValue(
        [Description("The configuration key to set")] string key,
        [Description("The new value")] string value)
    {
        AppConfiguration.Current[key] = value;
        return $"Updated {key} = {value}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/all", Name = "All Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAllConfig() =>
        JsonSerializer.Serialize(AppConfiguration.Current, AppConfiguration.JsonOptions);

    [McpServerResource(UriTemplate = "config://app/{section}", Name = "Configuration Section",
        MimeType = "application/json"),
     Description("Returns configuration values for a specific section.")]
    public static string GetConfigSection(string section)
    {
        var filtered = AppConfiguration.Current
            .Where(kv => kv.Key.StartsWith(section, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        return filtered.Count > 0
            ? JsonSerializer.Serialize(filtered, AppConfiguration.JsonOptions)
            : JsonSerializer.Serialize(new { error = $"No keys found for section '{section}'" });
    }
}

using System.Text.Json;

/// <summary>
/// Simple in-memory configuration store for demonstration purposes.
/// </summary>
public static class AppConfiguration
{
    public static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public static Dictionary<string, string> Current { get; } = new(StringComparer.OrdinalIgnoreCase)
    {
        ["App.Name"]        = "ConfigMcpServer",
        ["App.Version"]     = "1.0.0",
        ["App.Environment"] = "Development",
        ["Logging.Level"]   = "Information",
        ["Logging.Format"]  = "json",
        ["MaxRetries"]      = "3",
        ["TimeoutSeconds"]  = "30",
    };
}

